from __future__ import annotations

import base64
import json
import zlib
from functools import lru_cache
from typing import Any

_PACK = ""


@lru_cache(maxsize=1)
def load_era_public_pack() -> dict[str, Any]:
    payload = json.loads(zlib.decompress(base64.b64decode(_PACK)).decode("utf-8"))
    items = payload.get("items") or []
    if payload.get("timezone") != "Asia/Yerevan":
        raise RuntimeError("invalid_public_pack_timezone")
    if len(items) != 104:
        raise RuntimeError("invalid_public_pack_item_count")
    weeks = {int(item["week"]) for item in items}
    if weeks != set(range(1, 27)):
        raise RuntimeError("invalid_public_pack_weeks")
    polls = [item for item in items if item.get("kind") == "poll"]
    if len(polls) != 26:
        raise RuntimeError("invalid_public_pack_poll_count")
    if any(not item.get("body") and item.get("kind") != "poll" for item in items):
        raise RuntimeError("invalid_public_pack_empty_text")
    if any(item.get("kind") == "poll" and (not item.get("poll_question") or len(item.get("poll_options") or []) < 2) for item in items):
        raise RuntimeError("invalid_public_pack_poll")
    return payload


def public_pack_items() -> list[dict[str, Any]]:
    return list(load_era_public_pack()["items"])
